using System.Buffers.Text;
using System.Globalization;

namespace Arb.Core.Primitives;

/// <summary>
/// 64-bit time-sortable IDs: [0][41 bit ms since 2026-01-01][10 bit node][12 bit seq].
/// Generated by the engine (not the DB) so clientOrderId exists BEFORE an order leaves the process.
/// Lock-free (CAS), monotonic even if the wall clock steps backwards (logical clock: keeps counting
/// on the last issued millisecond, borrowing the next ms when 4096 IDs/ms are exhausted).
/// </summary>
public sealed class SnowflakeIdGenerator
{
    public const int NodeBits = 10;
    public const int SequenceBits = 12;
    public const int MaxNode = (1 << NodeBits) - 1;
    private const long SequenceMask = (1L << SequenceBits) - 1;
    private const long MaxMillis = (1L << 41) - 1;

    private readonly IClock _clock;
    private readonly long _nodeShifted;
    private long _state; // (ms << 12) | seq of the last issued id

    public SnowflakeIdGenerator(int nodeId, IClock clock)
    {
        if ((uint)nodeId > MaxNode)
        {
            throw new ArgumentOutOfRangeException(nameof(nodeId), nodeId, "0..1023");
        }

        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
        NodeId = nodeId;
        _nodeShifted = (long)nodeId << SequenceBits;
        _state = -1;
    }

    public static DateTimeOffset Epoch { get; } = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);

    public static long EpochUnixMs { get; } = Epoch.ToUnixTimeMilliseconds();

    public int NodeId { get; }

    public long Next()
    {
        while (true)
        {
            long now = (_clock.UnixMicros / 1000) - EpochUnixMs;
            if (now < 0 || now > MaxMillis)
            {
                throw new InvalidOperationException("clock outside Snowflake epoch range");
            }

            long cur = Volatile.Read(ref _state);
            long curMs = cur < 0 ? -1 : cur >> SequenceBits;
            long seq = cur < 0 ? 0 : cur & SequenceMask;
            long nextMs;
            long nextSeq;
            if (now > curMs)
            {
                nextMs = now;
                nextSeq = 0;
            }
            else if (seq == SequenceMask)
            {
                nextMs = curMs + 1;
                nextSeq = 0;
            }
            else
            {
                nextMs = curMs;
                nextSeq = seq + 1;
            }

            long next = (nextMs << SequenceBits) | nextSeq;
            if (Interlocked.CompareExchange(ref _state, next, cur) == cur)
            {
                return (nextMs << (SequenceBits + NodeBits)) | _nodeShifted | nextSeq;
            }
        }
    }

    public static long UnixMillisOf(long id) => (id >> (SequenceBits + NodeBits)) + EpochUnixMs;

    public static int NodeOf(long id) => (int)((id >> SequenceBits) & MaxNode);
}

/// <summary>
/// clientOrderId wire format: "a" + decimal id (≤ 20 chars) — valid for Binance newClientOrderId,
/// Bybit orderLinkId (≤ 36) and Bitget clientOid. Allocation-free.
/// </summary>
public static class ClientOrderId
{
    public const byte Prefix = (byte)'a';
    public const int MaxLength = 20;

    public static bool TryFormat(long id, Span<byte> destination, out int written)
    {
        written = 0;
        if (id <= 0 || destination.Length < 2)
        {
            return false;
        }

        destination[0] = Prefix;
        if (!id.TryFormat(destination[1..], out int n, default, CultureInfo.InvariantCulture))
        {
            return false;
        }

        written = n + 1;
        return true;
    }

    public static bool TryParse(ReadOnlySpan<byte> text, out long id)
    {
        id = 0;
        if (text.Length < 2 || text.Length > MaxLength || text[0] != Prefix)
        {
            return false;
        }

        return Utf8Parser.TryParse(text[1..], out id, out int consumed) && consumed == text.Length - 1 && id > 0;
    }
}
